package com.kidsvideo.app;
import org.json.JSONException; import org.json.JSONObject;
public final class VideoItem { public final String id,title,channelTitle,thumbnailUrl,category,publishedAt; public final long durationSeconds; public VideoItem(String id,String title,String channelTitle,String thumbnailUrl,String category,String publishedAt,long durationSeconds){this.id=id;this.title=title;this.channelTitle=channelTitle;this.thumbnailUrl=thumbnailUrl;this.category=category;this.publishedAt=publishedAt==null?"":publishedAt;this.durationSeconds=durationSeconds;} public JSONObject toJson() throws JSONException{JSONObject o=new JSONObject();o.put("id",id);o.put("title",title);o.put("channelTitle",channelTitle);o.put("thumbnailUrl",thumbnailUrl);o.put("category",category);o.put("publishedAt",publishedAt);o.put("durationSeconds",durationSeconds);return o;} public static VideoItem fromJson(JSONObject o){return new VideoItem(o.optString("id"),o.optString("title"),o.optString("channelTitle"),o.optString("thumbnailUrl"),o.optString("category"),o.optString("publishedAt"),o.optLong("durationSeconds"));} public String durationLabel(){long m=durationSeconds/60,s=durationSeconds%60;if(m>=60){long h=m/60,rm=m%60;return String.format("%d:%02d:%02d",h,rm,s);}return String.format("%d:%02d",m,s);} }
